// TestProbe_SoftFail asserts every ffprobe failure mode is SOFT (AC-6, INV3):
// missing binary, nonexistent path, and a directory all yield empty bytes + a
// non-empty warning + a nil err (the caller still identifies the file). These
// cases do not require ffprobe to be installed (except the path/dir ones, which
// are skipped if ffprobe is absent since they invoke it).
func TestProbe_SoftFail(t *testing.T) {
	t.Run("missing binary", func(t *testing.T) {
		t.Setenv("PATH", t.TempDir()) // PATH with no ffprobe
		data, warning, err := probe(context.Background(), "/tmp/anything.mkv")
		if err != nil {
			t.Fatalf("missing-binary err = %v, want nil (soft-fail)", err)
		}
		if data != nil {
			t.Fatalf("missing-binary data = %d bytes, want nil", len(data))
		}
		if warning == "" {
			t.Fatal("missing-binary warning empty, want non-empty")
		}
	})

	if _, err := exec.LookPath(ffprobeBin); err != nil {
		t.Skip("ffprobe absent: skipping ffprobe-dependent probe subtests")
	}

	dir := t.TempDir()
	cases := []struct {
		name string
		path string
	}{
		{"nonexistent path", filepath.Join(dir, "nope.mkv")},
		{"directory not a file", dir},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			data, warning, err := probe(context.Background(), tc.path)
			if err != nil {
				t.Fatalf("err = %v, want nil (soft-fail)", err)
			}
			if len(data) != 0 {
				t.Fatalf("data = %d bytes, want empty", len(data))
			}
			if warning == "" {
				t.Fatalf("warning empty for %s, want non-empty", tc.name)
			}
		})
	}
}

// TestProbe_RealFFprobe runs ffprobe against a tiny real media fixture and
// asserts probe returns valid JSON with an empty warning. Skips cleanly if
// ffmpeg (to generate the fixture) or ffprobe is absent — CI never fails on a
// missing toolchain (AC-6/B8 skip discipline).
func TestProbe_RealFFprobe(t *testing.T) {
	if _, err := exec.LookPath(ffprobeBin); err != nil {
		t.Skip("ffprobe not on PATH")
	}
	dir := t.TempDir()
	media := filepath.Join(dir, "clip.mkv")
	makeMedia(t, media)
	if info, err := os.Stat(media); err != nil || info.Size() == 0 {
		t.Skip("media fixture not generated (ffmpeg unavailable)")
	}

	data, warning, err := probe(context.Background(), media)
	if err != nil {
		t.Fatalf("probe err = %v, want nil", err)
	}
	if warning != "" {
		t.Fatalf("warning = %q, want empty for a valid media file", warning)
	}
	if !json.Valid(data) {
		t.Fatalf("ffprobe output is not valid JSON: %s", string(data))
	}
	var doc map[string]any
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatalf("ffprobe JSON unmarshal: %v", err)
	}
	if _, ok := doc["streams"]; !ok {
		t.Fatalf("ffprobe JSON missing 'streams': %s", string(data))
	}
}
